import { cva, type VariantProps } from "class-variance-authority";
import type { ButtonHTMLAttributes, HTMLAttributes, ReactNode } from "react";
import { cn, statusInfo } from "../lib/utils";

// shadcn-style primitives, written in the project rather than generated by the shadcn CLI.
export const buttonVariants = cva(
  "inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        primary: "bg-ember text-night-0 hover:bg-[#ff8d4f]",
        ghost: "border border-sand-2/60 text-sand-0 hover:border-sand-1 hover:bg-night-2",
        quiet: "text-sand-1 hover:bg-night-2 hover:text-sand-0",
      },
      size: {
        default: "",
        sm: "min-h-9 px-3 text-xs",
      },
    },
    defaultVariants: { variant: "primary", size: "default" },
  },
);

export function Button({
  className,
  variant,
  size,
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>) {
  return <button className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

export function Card({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("rounded-lg border border-sand-2/35 bg-night-1/90 backdrop-blur-sm", className)} {...props} />;
}

const toneClass = {
  ok: "border-ok/50 text-ok",
  bad: "border-bad/50 text-bad",
  ember: "border-ember/60 text-ember",
  sand: "border-sand-2/60 text-sand-1",
} as const;

export function StatusPill({ status }: { status: string }) {
  const info = statusInfo(status);
  return (
    <span className={cn("inline-flex items-center gap-2 rounded-full border px-2.5 py-0.5 text-xs", toneClass[info.tone])}>
      <span aria-hidden="true" className="size-1.5 rounded-full bg-current" />
      {info.label}
    </span>
  );
}

export function Label({ children }: { children: ReactNode }) {
  return <span className="text-xs uppercase tracking-[0.08em] text-sand-1">{children}</span>;
}
